  struct npool *ms = (struct npool *)ms_pool;

  if (ms->sslctx == NULL) {
    ssl_init_common(ms);
    ms->sslctx = ssl_init_helper(SSLv23_client_method());
  }
  return nsock_pool_ssl_init_helper(ms->sslctx, flags);
}

